-- PostgreSQL. Private tables are accessed only by the server; never expose them through a public data API.
BEGIN;
CREATE TABLE IF NOT EXISTS cities (slug text PRIMARY KEY,name_ar text NOT NULL,name_en text NOT NULL,landmark_ar text NOT NULL,landmark_en text NOT NULL,image text NOT NULL,active boolean NOT NULL DEFAULT false,position integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS districts (city_slug text NOT NULL REFERENCES cities(slug),slug text NOT NULL,name_ar text NOT NULL,name_en text NOT NULL,active boolean NOT NULL DEFAULT true,PRIMARY KEY(city_slug,slug));
CREATE TABLE IF NOT EXISTS partner_applications (id uuid PRIMARY KEY,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending_review' CHECK(status IN ('pending_review','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hotel_partners (id uuid PRIMARY KEY,application_id uuid REFERENCES partner_applications(id),legal_name text NOT NULL,contact_email text NOT NULL,identity_subject text UNIQUE,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hotels (id uuid PRIMARY KEY,partner_id uuid NOT NULL REFERENCES hotel_partners(id),slug text UNIQUE NOT NULL,name_ar text NOT NULL,name_en text NOT NULL,city_slug text NOT NULL,district_slug text NOT NULL,description_ar text NOT NULL,description_en text NOT NULL,photos jsonb NOT NULL DEFAULT '[]',photos_verified_at timestamptz,amenities jsonb NOT NULL DEFAULT '[]',classification integer CHECK(classification BETWEEN 1 AND 5),latitude double precision CHECK(latitude BETWEEN -90 AND 90),longitude double precision CHECK(longitude BETWEEN -180 AND 180),location_verified_at timestamptz,distance_m integer CHECK(distance_m>=0),distance_verified_at timestamptz,distance_source text,capacity integer NOT NULL CHECK(capacity>0),policies_ar text NOT NULL,policies_en text NOT NULL,sponsored boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','suspended')),FOREIGN KEY(city_slug,district_slug) REFERENCES districts(city_slug,slug),CHECK(distance_verified_at IS NULL OR (distance_m IS NOT NULL AND distance_source IS NOT NULL)),CHECK(location_verified_at IS NULL OR (latitude IS NOT NULL AND longitude IS NOT NULL)));
CREATE TABLE IF NOT EXISTS rooms (id uuid PRIMARY KEY,hotel_id uuid NOT NULL REFERENCES hotels(id),name_ar text NOT NULL,name_en text NOT NULL,capacity integer NOT NULL CHECK(capacity>0),inventory integer NOT NULL DEFAULT 0 CHECK(inventory>=0),room_type text NOT NULL,accessible boolean NOT NULL DEFAULT false,private_bathroom boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS stay_durations (code text PRIMARY KEY,hours integer CHECK(hours>0));
INSERT INTO stay_durations VALUES ('1',1),('3',3),('6',6),('12',12),('night',NULL) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS offers (id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES rooms(id),duration text NOT NULL REFERENCES stay_durations(code),price numeric(12,2) NOT NULL CHECK(price>=0),currency text NOT NULL DEFAULT 'SAR' CHECK(currency='SAR'),tax_included boolean NOT NULL DEFAULT false,fees jsonb NOT NULL DEFAULT '[]',booking_mode text NOT NULL DEFAULT 'request' CHECK(booking_mode IN ('request','instant')),valid_from date NOT NULL,valid_until date NOT NULL,arrival_from time,arrival_until time,active boolean NOT NULL DEFAULT false,hourly_approved_at timestamptz,inventory_provider text,cancellation_policy jsonb NOT NULL DEFAULT '{}',CHECK(valid_until>=valid_from),CHECK(duration='night' OR hourly_approved_at IS NOT NULL),CHECK(booking_mode='request' OR inventory_provider IS NOT NULL));
CREATE TABLE IF NOT EXISTS prices (id uuid PRIMARY KEY,offer_id uuid NOT NULL REFERENCES offers(id),effective_from timestamptz NOT NULL,amount numeric(12,2) NOT NULL CHECK(amount>=0),changed_by text NOT NULL);
CREATE TABLE IF NOT EXISTS availability (id uuid PRIMARY KEY,room_id uuid NOT NULL REFERENCES rooms(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,remaining integer NOT NULL CHECK(remaining>=0),source text NOT NULL,verified_at timestamptz NOT NULL,CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY,identity_subject text UNIQUE,email text NOT NULL,name text NOT NULL,mobile text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS booking_requests (id uuid PRIMARY KEY,offer_id uuid NOT NULL REFERENCES offers(id),hotel_id uuid NOT NULL REFERENCES hotels(id),customer_id uuid REFERENCES customers(id),payload jsonb NOT NULL,quoted_price numeric(12,2) NOT NULL,status text NOT NULL DEFAULT 'pending_hotel' CHECK(status IN ('pending_hotel','hotel_approved','declined','expired','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS confirmed_bookings (id uuid PRIMARY KEY,request_id uuid UNIQUE REFERENCES booking_requests(id),hotel_id uuid NOT NULL REFERENCES hotels(id),provider_reference text NOT NULL,confirmed_total numeric(12,2) NOT NULL,policy_snapshot jsonb NOT NULL,confirmed_at timestamptz NOT NULL,arrival timestamptz NOT NULL,departure timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('confirmed','completed','cancelled')),CHECK(departure>arrival));
CREATE TABLE IF NOT EXISTS commercial_agreements (id uuid PRIMARY KEY,partner_id uuid NOT NULL REFERENCES hotel_partners(id),model text NOT NULL CHECK(model IN ('commission','subscription','featured_ad','sponsored_listing','marketing_package','service_fee')),terms jsonb NOT NULL,publish_terms boolean NOT NULL DEFAULT false,starts_at timestamptz NOT NULL,ends_at timestamptz);
CREATE TABLE IF NOT EXISTS commissions (id uuid PRIMARY KEY,booking_id uuid NOT NULL REFERENCES confirmed_bookings(id),agreement_id uuid NOT NULL REFERENCES commercial_agreements(id),amount numeric(12,2) NOT NULL CHECK(amount>=0),status text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS promotions (id uuid PRIMARY KEY,hotel_id uuid NOT NULL REFERENCES hotels(id),title_ar text NOT NULL,title_en text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,sponsored boolean NOT NULL DEFAULT false,approved boolean NOT NULL DEFAULT false,CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY,actor_subject text NOT NULL,hotel_id uuid REFERENCES hotels(id),action text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY,count integer NOT NULL,expires bigint NOT NULL);
CREATE INDEX IF NOT EXISTS hotels_search_idx ON hotels(city_slug,district_slug,status);
CREATE INDEX IF NOT EXISTS offers_valid_idx ON offers(room_id,active,valid_from,valid_until);
CREATE INDEX IF NOT EXISTS requests_hotel_idx ON booking_requests(hotel_id,status,created_at);
COMMIT;
